import {structureSettings} from './structure-settings.js?v=20261008-structures';
const $=s=>document.querySelector(s);
export function mountStructures(api){
 const panel=document.createElement('section');panel.className='panel-section structure-panel';panel.innerHTML='<div class="section-heading"><span class="section-num">3D</span><h2>Bridges & tunnels</h2><span id="structure-count" class="scene-tag"></span></div><p class="field-hint">Select a road handle at the center of the span, then choose Bridge or Tunnel. Height, banking and smooth approach ramps are calculated automatically.</p><p id="structure-selection" class="field-hint"></p><div id="structure-controls"><label class="studio-field">Road structure<select id="structure-type"><option value="none">Normal road</option><option value="bridge">Bridge · raised deck</option><option value="tunnel">Tunnel · below ground</option></select></label><div class="studio-fields"><label class="studio-field">Covered span · m<input id="structure-length" type="number" min="12" max="120" step="2"></label><label class="studio-field">Clearance · m<input id="structure-clearance" type="number" min="4.5" max="12" step=".5"></label></div><label class="studio-field">Target ramp grade · %<input id="structure-grade" type="number" min="4" max="15" step="1"></label><p class="field-hint">The covered road is level and unbanked. Ramps blend into your existing elevations with smooth grades. On short layouts the grade may increase; the export report flags approaches that are too steep. Removing the structure restores your authored heights.</p><p id="structure-summary" class="structure-summary" role="status"></p><button id="structure-inspect" class="outline-button">Inspect structures in 3D</button></div><div id="structure-list" class="building-list"></div>';
 $('.corner-panel').after(panel);
 const change=()=>{const i=api.getSelected();if(i<0)return;for(const id of ['length','clearance','grade'])if(!$('#structure-'+id).checkValidity()){api.toast('Use a value inside the structure range shown.');refresh();return;}const value=structureSettings({type:$('#structure-type').value,length:Number($('#structure-length').value),clearance:Number($('#structure-clearance').value),grade:Number($('#structure-grade').value)});api.updateTrack(t=>t.points[i].structure=value);};
 for(const id of ['type','length','clearance','grade'])$('#structure-'+id).onchange=change;$('#structure-inspect').onclick=api.preview;
 let key='';function refresh(){const t=api.getTrack(),i=api.getSelected(),p=t.points[i],settings=structureSettings(p?.structure),profile=api.getGeometry().structureProfile,ranges=profile?.ranges||[],range=ranges.find(r=>r.index===i);$('#structure-count').textContent=`${ranges.length} / 16`;$('#structure-selection').textContent=p?`Selected road handle ${i+1}. Structure changes apply to this handle.`:'Choose a road handle in Move or the Corner workshop to place a span.';$('#structure-controls').hidden=!p;
  for(const id of ['type','length','clearance','grade']){$('#structure-'+id).value=settings[id];$('#structure-'+id).disabled=id!=='type'&&settings.type==='none';}
  $('#structure-summary').textContent=range?`${range.type==='bridge'?'Deck':'Road floor'} ${range.level.toFixed(1)} m · ${range.span.toFixed(0)} m covered · ${range.ramp.toFixed(0)} m approach each side · estimated ${range.estimatedGrade.toFixed(1)}% peak ramp. ${(profile.issues||[]).filter(issue=>issue.includes('Handle '+(i+1)+':')||issue.includes('handles')).join(' ')}`:'Choose a structure to generate its automatic elevation profile.';
  const next=JSON.stringify([ranges,i]);if(next===key)return;key=next;const list=$('#structure-list');list.replaceChildren();for(const r of ranges){const b=document.createElement('button');b.className='outline-button';b.textContent=`${r.type==='bridge'?'Bridge':'Tunnel'} · handle ${r.index+1} · ${r.span.toFixed(0)} m`;b.onclick=()=>{api.selectPoint(r.index);api.focusProgress(r.center/(api.getGeometry().length*(t.scale||.2)));};list.append(b);}
 }
 return {refresh};
}
